import { describe, it, expect, vi, afterEach } from 'vitest'
import { nextTick, effectScope } from 'vue'

import { usePaging, toStartEndIndex } from '@/utils/page.js'

describe('toStartEndIndex', () => {
	it('page/pageSize 를 start/end 인덱스로 변환한다', () => {
		expect(toStartEndIndex(1, 10)).toEqual({ start: 0, end: 9 })
		expect(toStartEndIndex(3, 20)).toEqual({ start: 40, end: 59 })
	})

	it('0 이하/비정상 값은 최소값으로 보정한다', () => {
		expect(toStartEndIndex(0, 10)).toEqual({ start: 0, end: 9 })
		expect(toStartEndIndex(-5, 0)).toEqual({ start: 0, end: 0 })
		expect(toStartEndIndex(null, null)).toEqual({ start: 0, end: 0 })
	})
})

describe('usePaging', () => {
	const scopes = []
	const createPaging = (...args) => {
		const scope = effectScope()
		scopes.push(scope)
		return scope.run(() => usePaging(...args))
	}
	afterEach(() => scopes.splice(0).forEach(scope => scope.stop()))

	it('기본값을 설정한다', () => {
		const { page, pageSize, totalCount, totalPages } = createPaging()
		expect(page.value).toBe(1)
		expect(pageSize.value).toBe(20)
		expect(totalCount.value).toBe(0)
		expect(totalPages.value).toBe(1)
	})

	it('totalCount / pageSize 로 전체 페이지 수를 계산한다', () => {
		const { setTotalCount, pageSize, totalPages } = createPaging(null, { pageSize: 10 })
		setTotalCount(95)
		expect(totalPages.value).toBe(10)

		pageSize.value = 30
		expect(totalPages.value).toBe(4)
	})

	it('페이지가 바뀌면 목록 조회 콜백을 호출한다', async () => {
		const onGetList = vi.fn()
		const { setPage } = createPaging(onGetList)

		setPage(3)
		await nextTick()

		expect(onGetList).toHaveBeenCalledTimes(1)
	})

	it('resetPageAndGet 은 1페이지로 되돌리고 조회한다', async () => {
		const onGetList = vi.fn()
		const { page, setPage, resetPageAndGet } = createPaging(onGetList)

		setPage(5)
		await nextTick()
		onGetList.mockClear()

		resetPageAndGet()
		expect(page.value).toBe(1)
		expect(onGetList).toHaveBeenCalledTimes(1)
		await nextTick()
		expect(onGetList).toHaveBeenCalledTimes(1)
	})

	it.each([1, 5])('페이지 %i 초기화는 실제 조회 Promise의 완료와 결과를 전달한다', async (initialPage) => {
		const requests = []
		let complete
		const response = new Promise(resolve => { complete = resolve })
		const paging = createPaging(() => {
			requests.push(paging.page.value)
			return response
		}, { page: initialPage })
		const result = paging.resetPageAndGet()
		expect(paging.page.value).toBe(1)
		expect(result).toBe(response)
		let finished = false
		result.then(() => { finished = true })
		await nextTick()
		expect(finished).toBe(false)
		expect(requests).toEqual([1])
		complete('loaded')
		await expect(result).resolves.toBe('loaded')
		await nextTick()
		expect(finished).toBe(true)
